  "Install / update agent": "에이전트 설치 / 업데이트",
  "From the ACP Registry": "ACP Registry에서",
  "The ACP Registry is the public catalog of coding agents built on the Agent Client Protocol, an open standard that lets any app drive any agent. The app installs the agent you pick on this machine. {a}":
    "ACP Registry는 Agent Client Protocol로 만든 코딩 에이전트의 공개 카탈로그입니다. Agent Client Protocol은 어떤 앱이든 어떤 에이전트든 구동할 수 있게 해 주는 개방형 표준입니다. 앱은 선택한 에이전트를 이 컴퓨터에 설치합니다. {a}",
  "About ACP": "ACP 정보",
  "More agents": "더 많은 에이전트",
