  "Add an API account": "API 계정 추가",
  "Turns on this account are billed per token to its credits at API prices, not to your subscription. Create the key in the {console}. Add one account per key; when one runs out of credits, a stopped thread can continue on the next.":
    "이 계정의 턴은 구독이 아니라 계정 크레딧에서 API 가격으로 토큰당 청구됩니다. 키는 {console}에서 만드세요. 키마다 계정을 하나씩 추가하세요. 한 계정의 크레딧이 떨어지면 중지된 스레드가 다음 계정에서 이어서 진행할 수 있습니다.",
  "API key": "API 키",
  "Workspace ID (optional)": "워크스페이스 ID(선택)",
  "A workspace ID starts with wrkspc_.": "워크스페이스 ID는 wrkspc_로 시작합니다.",
  "Needed for a key that is not scoped to a workspace (user keys, sk-ant-usr…). Copy it from Settings → Workspaces in the Claude Console.":
    "워크스페이스로 범위가 지정되지 않은 키(사용자 키, sk-ant-usr…)에 필요합니다. Claude Console의 Settings → Workspaces에서 복사하세요.",
  "Name (optional)": "이름(선택)",
