  "Add ChatGPT account": "ChatGPT 계정 추가",
  "e.g. Personal or Work": "예: 개인 또는 업무",
  "Add an account or configure a provider on {environmentLabel}.":
    "{environmentLabel}에 계정을 추가하거나 제공업체를 구성하세요.",
  "Built-in providers": "기본 제공 제공업체",
  "Grok runs the grok CLI already on {environmentLabel}. No CLI there? Add Grok Build below instead; it installs Grok as its own registry agent.":
    "Grok은 {environmentLabel}에 이미 있는 grok CLI를 실행합니다. CLI가 없나요? 아래에서 Grok Build를 추가하세요. Grok을 별도의 레지스트리 에이전트로 설치합니다.",
  "Enter an official registry ID and any local executable or auth override.":
    "공식 레지스트리 ID와 필요한 경우 로컬 실행 파일 또는 인증 재정의를 입력하세요.",
  "Search registry": "레지스트리 검색",
  Docs: "문서",
  Label: "레이블",
  "Shown in the provider list.": "제공업체 목록에 표시됩니다.",
  "e.g. Work": "예: 업무",
  "Instance ID": "인스턴스 ID",
  "Letters, digits, '-', or '_'.": "문자, 숫자, '-' 또는 '_'.",
  "This driver has no required configuration. You can add the instance now.":
    "이 드라이버는 필수 구성이 없습니다. 지금 인스턴스를 추가할 수 있습니다.",
  Back: "뒤로",
  "Configure manually": "직접 구성",
