  "More actions for this machine": "이 컴퓨터의 추가 작업",
  "Up to date": "최신 상태",
  "This connection can create access links but cannot view authorized clients.":
    "이 연결은 액세스 링크를 만들 수 있지만 승인된 클라이언트는 볼 수 없습니다.",
  "Enable network access?": "네트워크 액세스를 사용할까요?",
  "Disable network access?": "네트워크 액세스를 끌까요?",
  "Let your other devices connect to SpecWithCode over your local network. This mode uses plain HTTP, so its traffic is not encrypted: anyone on the same network can capture the sign-in and use it to control the app. Turn it on only on a network you trust, and use SpecWithCode Connect or Tailscale HTTPS for remote access. Pair devices to give them access. The app will restart.":
    "다른 기기가 로컬 네트워크를 통해 SpecWithCode에 연결하도록 허용합니다. 이 모드는 일반 HTTP를 사용하므로 트래픽이 암호화되지 않습니다. 같은 네트워크의 누구나 로그인 정보를 가로채 앱을 제어할 수 있습니다. 신뢰하는 네트워크에서만 켜고, 원격 액세스에는 SpecWithCode Connect나 Tailscale HTTPS를 사용하세요. 기기에 액세스 권한을 주려면 페어링하세요. 앱이 다시 시작됩니다.",
  "Devices connected over your local network will disconnect. Existing tunnels, such as SpecWithCode Connect or Tailscale HTTPS, keep working. SpecWithCode will restart.":
    "로컬 네트워크로 연결된 기기의 연결이 끊어집니다. SpecWithCode Connect나 Tailscale HTTPS 같은 기존 터널은 계속 작동합니다. SpecWithCode가 다시 시작됩니다.",
  "Restarting…": "다시 시작하는 중…",
  "Restart and enable": "다시 시작하고 사용",
  "Restart and disable": "다시 시작하고 끄기",
  "Turn off WSL and switch back to Windows?": "WSL을 끄고 Windows로 돌아갈까요?",
  "Disable WSL backend?": "WSL 백엔드를 끌까요?",
  "Switch WSL distro?": "WSL 배포판을 바꿀까요?",
  "Start the WSL backend": "WSL 백엔드 시작",
  "Run only the WSL backend?": "WSL 백엔드만 실행할까요?",
  "Re-enable the Windows backend?": "Windows 백엔드를 다시 사용할까요?",
  "SpecWithCode will restart on the Windows backend. Threads and projects opened against WSL stay safe inside the distro and become available again when you re-enable WSL.":
    "SpecWithCode가 Windows 백엔드에서 다시 시작됩니다. WSL에서 연 스레드와 프로젝트는 배포판 안에 안전하게 남아 있으며 WSL을 다시 켜면 다시 사용할 수 있습니다.",
  "The WSL backend will stop. Threads and projects opened against WSL stay safe inside the distro, but they'll be unavailable in SpecWithCode until you re-enable WSL.":
    "WSL 백엔드가 중지됩니다. WSL에서 연 스레드와 프로젝트는 배포판 안에 안전하게 남지만, WSL을 다시 켤 때까지 SpecWithCode에서 사용할 수 없습니다.",
  "SpecWithCode will restart the WSL backend on the new distro. Sessions still running on the current distro will be interrupted.":
    "SpecWithCode가 새 배포판에서 WSL 백엔드를 다시 시작합니다. 현재 배포판에서 실행 중인 세션은 중단됩니다.",
  "Run the WSL backend alongside the Windows one, or stop the Windows backend and use only WSL? You can change this later from Settings.":
    "WSL 백엔드를 Windows 백엔드와 함께 실행할까요, 아니면 Windows 백엔드를 중지하고 WSL만 사용할까요? 나중에 설정에서 바꿀 수 있습니다.",
  "SpecWithCode will restart and start only the WSL backend. Your Windows-side projects won't be accessible until you turn this off again.":
    "SpecWithCode가 다시 시작되어 WSL 백엔드만 실행합니다. 이 옵션을 다시 끌 때까지 Windows 쪽 프로젝트에는 액세스할 수 없습니다.",
  "SpecWithCode will restart and bring the Windows backend back up alongside WSL.":
    "SpecWithCode가 다시 시작되어 WSL과 함께 Windows 백엔드를 다시 실행합니다.",
  "Applying…": "적용하는 중…",
  "Use only WSL": "WSL만 사용",
  "Run both backends": "두 백엔드 모두 실행",
  "Disable WSL": "WSL 끄기",
  "Switch distro": "배포판 전환",
  "Disable Tailscale HTTPS?": "Tailscale HTTPS를 끌까요?",
  "SpecWithCode will restart the local backend without Tailscale Serve.":
    "SpecWithCode가 Tailscale Serve 없이 로컬 백엔드를 다시 시작합니다.",
  "Tailscale will stop serving HTTPS for the SpecWithCode service on this computer.":
    "Tailscale이 이 컴퓨터의 SpecWithCode 서비스에 대한 HTTPS 제공을 중지합니다.",
  "Set up Tailscale HTTPS?": "Tailscale HTTPS를 설정할까요?",
  "SpecWithCode will restart the local backend with Tailscale Serve enabled and ask Tailscale to proxy HTTPS traffic to this backend.":
    "SpecWithCode가 Tailscale Serve를 켠 상태로 로컬 백엔드를 다시 시작하고, 이 백엔드로 HTTPS 트래픽을 프록시하도록 Tailscale에 요청합니다.",
  "Tailscale will serve HTTPS on your tailnet and forward it to the SpecWithCode service on this computer.":
    "Tailscale이 tailnet에서 HTTPS를 제공하고 이 컴퓨터의 SpecWithCode 서비스로 전달합니다.",
