  "Update the server to share logins with agents":
    "에이전트와 로그인을 공유하려면 서버를 업데이트하세요",
  "Connect to an environment to clear profile data": "프로필 데이터를 지우려면 환경에 연결하세요",
  "Remove “{name}”?": "'{name}'을(를) 제거할까요?",
  "Its cookies and logins are deleted. Desktop tabs already open in this profile stay open until you close them; server browser tabs close now.":
    "쿠키와 로그인 정보가 삭제됩니다. 이 프로필에 이미 열려 있는 데스크톱 탭은 닫을 때까지 열려 있고, 서버 브라우저 탭은 지금 닫힙니다.",
  "Connect to an environment to remove this profile and its data.":
    "이 프로필과 데이터를 제거하려면 환경에 연결하세요.",
  "Remove profile": "프로필 제거",
  "Clear “{name}”’s cookies and cache?": "'{name}'의 쿠키와 캐시를 지울까요?",
