  "Works once, until {expiresAt}. Paste it only into SpecWithCode on {machineLabel}, not into a chat.":
    "{expiresAt}까지 한 번만 작동합니다. {machineLabel}의 SpecWithCode에만 붙여 넣고 채팅에는 붙여 넣지 마세요.",
  Updates: "업데이트",
  "Service {currentVersion}": "서비스 {currentVersion}",
  "Machine unreachable. Saved update permission has not changed.":
    "컴퓨터에 연결할 수 없습니다. 저장된 업데이트 권한은 바뀌지 않았습니다.",
  "Update status unavailable. Permission has not been changed.":
    "업데이트 상태를 확인할 수 없습니다. 권한은 변경되지 않았습니다.",
  "Reading update status…": "업데이트 상태를 읽는 중…",
