  " Use the installed app on this machine.": " 이 컴퓨터에 설치된 앱을 사용하세요.",
  " Being connected does not grant update permission.":
    " 연결되어 있다고 업데이트 권한이 부여되지는 않습니다.",
  "Checking for updates requires permission for this connection.":
    "업데이트를 확인하려면 이 연결에 권한이 필요합니다.",
  "This connection does not have maintenance access to check for updates.":
    "이 연결에는 업데이트를 확인할 유지 관리 권한이 없습니다.",
  "Check for updates finds releases; it does not download or install them.":
    "업데이트 확인은 릴리스를 찾기만 하며, 다운로드하거나 설치하지 않습니다.",
  "Update request was refused or failed. Refresh status and try again; changed permissions require fresh approval.":
    "업데이트 요청이 거부되었거나 실패했습니다. 상태를 새로 고친 뒤 다시 시도하세요. 권한이 바뀌면 새로 승인해야 합니다.",
  "Talk to a project's coordinator from your phone, like a personal agent. Messages you send become work for the coordinator on this machine, and its answers, your routines' results and waiting approvals come back to the chat.":
    "개인 에이전트처럼 휴대폰에서 프로젝트 코디네이터와 대화하세요. 보낸 메시지는 이 컴퓨터의 코디네이터 작업이 되고, 그 답변, 루틴 결과, 대기 중인 승인이 채팅으로 돌아옵니다.",
  "This machine calls Telegram; nothing on it is opened to the internet. Only the one chat that sends the pairing code can reach the coordinator, and approvals still happen in SpecWithCode. Answers arrive while this machine is awake.":
    "이 컴퓨터가 Telegram을 호출하므로 이 컴퓨터의 어떤 것도 인터넷에 공개되지 않습니다. 페어링 코드를 보낸 채팅 하나만 코디네이터에 닿을 수 있으며, 승인은 계속 SpecWithCode에서 이루어집니다. 답변은 이 컴퓨터가 깨어 있는 동안 도착합니다.",
  "The SpecWithCode service this app is connected to (version {serverVersion}) is older than the Telegram channel. Update that service to use it.":
    "이 앱이 연결된 SpecWithCode 서비스(버전 {serverVersion})는 Telegram 채널 이전 버전입니다. 사용하려면 해당 서비스를 업데이트하세요.",
  "Bot token": "봇 토큰",
  "Telegram bot token": "Telegram 봇 토큰",
  "In Telegram, message @BotFather, send /newbot and paste the token it gives you. It stays on this machine.":
    "Telegram에서 @BotFather에게 메시지를 보내고 /newbot을 보낸 뒤 받은 토큰을 붙여 넣으세요. 토큰은 이 컴퓨터에 남습니다.",
  "That does not look like a bot token. It has digits, a colon, then letters.":
    "봇 토큰처럼 보이지 않습니다. 숫자, 콜론, 문자 순으로 되어 있습니다.",
  "Project for the Telegram channel": "Telegram 채널용 프로젝트",
  "{value}Messages go to this project's coordinator. {value2}":
    "{value}메시지는 이 프로젝트의 코디네이터에게 전달됩니다. {value2}",
  "Off stops listening; the pairing is kept.": "끄면 수신을 멈추며 페어링은 유지됩니다.",
  "Telegram channel on": "Telegram 채널 켜짐",
  "Connect bot": "봇 연결",
  "Unpair chat": "채팅 페어링 해제",
  "Paired with {span}{value}.": "{span}{value}과(와) 페어링됨.",
  "your chat": "내 채팅",
  "Open the bot in Telegram": "Telegram에서 봇 열기",
  "Pair your phone": "휴대폰 페어링",
  "Scan the code with your phone, or open {value} and send:":
    "휴대폰으로 코드를 스캔하거나 {value}을(를) 열고 다음을 보내세요:",
  "The code works once and expires in 30 minutes. This page updates when the chat pairs.":
    "코드는 한 번만 작동하며 30분 후에 만료됩니다. 채팅이 페어링되면 이 페이지가 업데이트됩니다.",
  "The pairing code expired. Press Save to get a new one.":
    "페어링 코드가 만료되었습니다. 저장을 누르면 새 코드를 받습니다.",
  "No models configured for this lane. Workers keep their baseline model.":
    "이 레인에 구성된 모델이 없습니다. 워커는 기본 모델을 유지합니다.",
