  "No learned model preferences yet. Rules are learned when you give feedback in chat, or can be recorded by the coordinator.":
    "아직 학습된 모델 선호가 없습니다. 채팅에서 피드백을 주면 규칙이 학습되며, 코디네이터가 기록할 수도 있습니다.",
  "Feedback: “{note}”": '피드백: "{note}"',
  "Turn on": "켜기",
  "Review and approve": "검토 및 승인",
  "Turn off": "끄기",
  "Draws its own commands and panes only.": "자체 명령과 창만 그립니다.",
  "Stopped with an error: {runtimeError}": "오류로 중지됨: {runtimeError}",
  "Mods add commands, panes and status to the workbench. Each runs in a sandbox with no network, files or credentials, and only after you approve its exact contents. Any edit pauses it until you approve again.":
    "모드는 작업대에 명령, 창, 상태를 추가합니다. 각 모드는 네트워크, 파일, 자격 증명이 없는 샌드박스에서, 그리고 정확한 내용을 승인한 후에만 실행됩니다. 수정하면 다시 승인할 때까지 일시 중지됩니다.",
  "{value} {span}. Check a mod with {span2}.": "{value} {span}. {span2}(으)로 모드를 확인하세요.",
  "Folder on this host:": "이 호스트의 폴더:",
  "The SpecWithCode service this app is connected to{value} is older than Mods, so it has no mods to show. Update that service to list, approve and run mods.":
    "이 앱이 연결된 SpecWithCode 서비스{value}는 모드 이전 버전이어서 표시할 모드가 없습니다. 모드를 나열, 승인, 실행하려면 해당 서비스를 업데이트하세요.",
  "No mods on this host yet.": "이 호스트에는 아직 모드가 없습니다.",
  "Approve {name}?": "{name}을(를) 승인할까요?",
  "Read the files in {value}/{name} first. This approves exactly the contents with this fingerprint; the CLI's validate command prints the same one.":
    "먼저 {value}/{name}의 파일을 읽어 보세요. 이 지문을 가진 내용만 정확히 승인합니다. CLI의 validate 명령도 같은 지문을 출력합니다.",
  "It asks for no permissions beyond drawing its own UI.":
    "자체 UI를 그리는 것 외에는 어떤 권한도 요청하지 않습니다.",
  "A mod can never answer approvals, grant folders, choose accounts or start a turn.":
    "모드는 승인 요청에 응답하거나, 폴더를 부여하거나, 계정을 고르거나, 턴을 시작할 수 없습니다.",
