  "Long audio is transcribed first (speech to text), the transcript is split into chunks that fit the model's context, and the cheaper model works through the chunks. Auto never sends audio to a model that cannot hear it.":
    "긴 오디오는 먼저 전사(음성을 텍스트로)되고, 전사본은 모델의 컨텍스트에 맞는 조각으로 나뉘며, 더 저렴한 모델이 조각을 차례로 처리합니다. Auto는 오디오를 들을 수 없는 모델에 오디오를 보내지 않습니다.",
  "A failure on the cheaper model gets one retry on the model the work would have used without Auto. Model changes happen only between turns.":
    "더 저렴한 모델에서 실패하면 Auto가 없었을 때 사용했을 모델로 한 번 다시 시도합니다. 모델 변경은 턴 사이에만 일어납니다.",
  "Routing conflicts": "라우팅 충돌",
  "task tiers": "작업 등급",
  "Default ({value})": "기본값({value})",
  "Let Auto use paid API models?": "Auto가 유료 API 모델을 사용하도록 허용할까요?",
  "Workers in this project may run on providers billed per token, up to the tier you picked. Those turns are billed to the provider's API account at API rates. SpecWithCode cannot read or cap that balance; set a spend limit with the provider.":
    "이 프로젝트의 워커는 선택한 등급까지 토큰당 과금되는 제공업체에서 실행될 수 있습니다. 이러한 턴은 API 요금으로 제공업체의 API 계정에 청구됩니다. SpecWithCode는 그 잔액을 읽거나 제한할 수 없으니 제공업체에서 지출 한도를 설정하세요.",
  "Workers may run on providers billed per token, up to the tier you picked, in every project that does not override this. Those turns are billed to the provider's API account at API rates. SpecWithCode cannot read or cap that balance; set a spend limit with the provider.":
    "워커는 이 설정을 재정의하지 않은 모든 프로젝트에서 선택한 등급까지 토큰당 과금되는 제공업체에서 실행될 수 있습니다. 이러한 턴은 API 요금으로 제공업체의 API 계정에 청구됩니다. SpecWithCode는 그 잔액을 읽거나 제한할 수 없으니 제공업체에서 지출 한도를 설정하세요.",
  "Allow paid API": "유료 API 허용",
  "The team rules file has an error, so no agent turn can start on this machine. Fixing the file resumes agents without a restart.{value}":
    "팀 규칙 파일에 오류가 있어 이 컴퓨터에서는 에이전트 턴을 시작할 수 없습니다. 파일을 고치면 재시작 없이 에이전트가 다시 작동합니다.{value}",
  "See {contact}.": "{contact}을(를) 참고하세요.",
